
# Purpose of this script is to automate validation analysis for SIT FUSE products 
# from output_vals.pkl file generated by running hab_post_inference_pipeline.py
#
# Notes on output_vals.pkl file:
#   context_data['validation'] is a list of tuples, where
#   each tuple is a row in the confusion matrix structured like this: 
    #     ([row_vector], [bin_edges], severity_bin * 1000)
    #       row_vector is a given severity class's row of the confusion matrix (prediction counts), 
    #       bin_edges is the upper limit of cell/toxin concentration that defines that severity bin,
    #       severity_bin gives the bin index (#)
    #       
    #       Example: 
    #       x['validation']['Total_Phytoplankton']['s3a']['no_trop']

    #       {'validation': [[(array([0, 0, 3, 0, 0, 0]), array([        0,      1000,     10000,    100000,   1000000,  10000000,
    #        100000000]), 3000), (array([ 0,  2,  6, 14,  0,  0]), array([        0,      1000,     10000,    100000,   1000000,  10000000,
    #        100000000]), 4000), (array([0, 0, 0, 0, 1, 0]), array([        0,      1000,     10000,    100000,   1000000,  10000000,
    #        100000000]), 5000)]]}
    #
    #       [0, 0, 3, 0, 0, 0] is the row vector, 
    #       [        0,      1000,     10000,    100000,   1000000,  10000000,  100000000] is the bin edges,
    #       3 is the severity bin 

#Example command line prompt: 
#python src/sit_fuse/pipelines/habs/hab_validation_analysis_ERDA.py "D:\Users\charlotte.rhoads\Downloads\output_vals.pkl"

# Terminology in this script: 
# instrument = the satellite platform carrying the ocean color sensor, i.e ['pace', 'aqua_modis', 's3a', 's3b', 'jpss1', 'snpp']
# product = the specific SIT FUSE phytoplankton product, i.e ['pDA', 'Pseudo_nitzschia_delicatissima_group', 'Pseudo_nitzschia_seriata_group', 'Total_Phytoplankton']
# bin (also severity, severity class) = severity classification predicted by SIT FUSE, derived from each row tuple's third value (severity * 1000)
# context = either no tropomi or tropomi ['no_trop', 'trop], set in hab_post_inference_pipeline.py

import argparse
import csv
import json
import pickle
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

import matplotlib
import yaml
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np

