XLABEL_PRODUCT = ["Particulate Domoic Acid", r'$\mathit{P. Delicatissima}$', r'$\mathit{P. Seriata}$', "Total Phytoplankton"]
XLABEL_SEVERITY = ["0", "1", "2", "3", "4", "5"]
 
